"""Guía de entradas y lectura de resultados para cada ruta pública."""
GUIDES={}
def add(kind,task,flow,parameters,reading):
    GUIDES[kind,task]={'flow':tuple(flow.split('|')),'parameters':[tuple(row.split(': ',1)) for row in parameters.split('\n') if row],'reading':reading}
SEQUENCE='Entrada: Fórmula en n o muestras separadas por coma; para decimales usá punto. Ejemplo: 1, -0.5, 2.\nInicio y cantidad: Inicio es el índice de la primera muestra; cantidad es cuántos valores generar, no el índice final. Último índice = inicio + cantidad − 1.'
TRANSFER='Dominio: Continuo usa H(s); discreto usa H(z).\nCoeficientes b y a: En continuo se ordenan por potencias descendentes de s; en discreto por 1, z⁻¹, z⁻²… Conservá los ceros intermedios. El primer coeficiente del denominador debe ser distinto de cero.'
MATRICES='A, B, C y D: Si hay r estados, m entradas y p salidas: A es r×r, B r×m, C p×r y D p×m. Cada celda contiene un coeficiente.\nDominio y período: En continuo se usa dx/dt; en discreto x[k+1]. El período discreto T es positivo y se expresa en segundos.'
for task,flow,extra,reading in [
('generate','Fórmula o valores|x[n], n = n₀…n₀+N−1|Muestras sobre su índice','Fórmula: Usá n, por ejemplo cos(pi*n/4). En Por tramos, cada fila indica valor y condición.','Los tallos representan muestras independientes. Parte real conserva los signos; módulo muestra valores absolutos.'),
('measures','Registro finito|E = Σ|x[n]|²|P = E/N; RMS = √P','','El promedio se refiere al registro cargado. No demuestra la energía ni la potencia de una extensión infinita.'),
('shift','x[n] y desplazamiento k|y[n] = x[n−k]|Mismo valor, índice nuevo','Desplazamiento k: Entero positivo mueve a la derecha; negativo mueve a la izquierda.','El cambio se observa en el eje horizontal, no en las amplitudes.'),
('reverse','x[n] con su origen|y[n] = x[−n]|Eje invertido','','La primera muestra de salida corresponde al negativo del último índice de entrada.'),
('scale','x[n] y factor A|y[n] = A x[n]|Amplitud escalada','Factor A: Multiplica amplitudes; un valor negativo invierte el signo. No cambia los índices.','Usá parte real para ver una inversión de signo; el módulo no la distingue.'),
('parity','x[n] y x[−n]|Mitad de suma / diferencia|Partes par e impar','','Se supone cero fuera del registro. Par + impar recupera la señal sobre el soporte extendido.'),
('dft','N muestras x[n]|X[k] = Σ x[n]e⁻ʲ²πᵏⁿ/ᴺ|N coeficientes discretos','','La frecuencia ωk=2πk/N se muestra centrada en cero, dentro de −π ≤ ωk < π. La directa conserva N bins y no divide por N.'),
('idft','X[0]…X[N−1]|Inversa con factor 1/N|Secuencia desde n = 0','Orden de entrada: Para una lista manual, ingresá los coeficientes desde k=0. Al reutilizar una DFT centrada, la inversa reconoce su orden.','Un espectro sin simetría conjugada puede producir una señal compleja.'),
('sum','x[n] y h[n]|Alinear índices y sumar|y[n] = x[n]+h[n]','Segunda entrada: Tiene su propio origen. Los tramos sin muestras se completan con cero.','No se suman simplemente las filas si los índices iniciales son distintos.'),
('convolve','x[n] y h[n]|Σ x[k]h[n−k]|Salida de N+M−1 muestras','Segunda entrada: Definí h y su origen por separado.','El origen de salida es la suma de los orígenes. No confundir convolución con multiplicación muestra a muestra.'),
('circular','Dos registros|Convolución con vuelta periódica|Un período de salida','Longitud: Se usa la mayor longitud de entrada y se completa la otra con ceros.','La salida circular puede superponer extremos; no equivale a la convolución lineal sin relleno suficiente.')]:add('basic',task,flow,SEQUENCE+('\n'+extra if extra else ''),reading)
add('basic','continuous_convolve','x(t), h(t) y paso Δt|Integral de productos desplazados|y(t)', 'Entradas: Dos registros con igual paso temporal positivo. Cada uno tiene su propio inicio.\nCantidad y paso: El final es inicio+(cantidad−1)·paso. Fuera del registro se supone cero.', 'La curva es una aproximación numérica. El paso afecta la integración; la ventana temporal limita qué parte de las señales se conoce.')
add('signal_editor',0,'Índices y valores|Editar tabla y aplicar|Nuevo registro reutilizable','Nombre: Identifica la salida, no modifica los valores.\nOrigen y paso: Determinan el eje. En una secuencia los índices deben ser enteros y el paso positivo.\nTabla: Cada fila representa una muestra; editar no equivale a exportar: aplicá los cambios.','El gráfico y la exportación corresponden a los cambios aplicados; revisá el eje además de los valores.')
add('time_transform',0,'x(t), A, a y t₀|y(t)=A x(a(t−t₀))|Eje y amplitud transformados','A: Factor de amplitud; negativo invierte el signo.\na: Escala temporal no nula. |a|>1 comprime; 0<|a|<1 expande; a<0 invierte el tiempo.\nt₀: Desplazamiento final en segundos; positivo hacia la derecha. Para x(2t−4), a=2 y t₀=2.','Cada instante τ pasa a τ/a+t₀. La herramienta transforma el registro disponible, sin inventar valores fuera de él.')
for task in ('interval','global','periodic'):
    add('expression_measures',task,'Expresión y dominio|'+{'interval':'Integrar o sumar |x|² en límites','global':'Examinar energía y potencia globales','periodic':'Promediar |x|² en un período'}[task]+'|Medidas y condiciones','Expresión y dominio: t para continuo; n para discreto. Incluí los tramos que definen el soporte.\nLímites o período: En intervalo se analiza sólo ese tramo; en periódico se usa un período positivo. En discreto el período se mide en muestras enteras.\nAproximación numérica: La ventana y puntos sólo controlan la aproximación disponible, no prueban convergencia global.','Distingue finito, divergente, condicional y pendiente. Una expresión no evaluada no equivale a cero.')
for task in (0,1):
    add('correlation',task,'x y h (o sólo x)|Desplazar y conjugar h|Correlación por retardo','Entradas: Auto usa x con ella misma; cruzada usa x y h. El orden fija el signo del retardo.\nModelo: Registro finito supone cero fuera; circular o periódico repite un período.\nEscala: Suma/integral conserva la escala; coeficiente por energía requiere energías no nulas; promedio periódico divide por el período.','El eje es retardo, no tiempo de la señal original. Un máximo indica alineación según la convención indicada, no causalidad.')
for kind in ('convolution_algebra','correlation_algebra'):
    add(kind,0,'Expresiones x(t), h(t)|'+('∫ x(τ)h(t−τ)dτ' if kind=='convolution_algebra' else '∫ x(t)conj(h(t−τ))dt')+'|Fórmula y condiciones','Expresiones: Usá t e incluí escalones o condiciones por tramos cuando corresponda.\n'+('Soporte: Causal supone cero para t<0; bilateral requiere que las expresiones incluyan su soporte.' if kind=='convolution_algebra' else 'Período: Vacío solicita integral bilateral. Un período positivo exige que ambas expresiones sean periódicas con ese período; no se divide por él.'),'Un resultado pendiente de evaluación no es una función cero. La correlación conjuga la segunda señal; la convolución no.')
for task,flow,parameters,reading in [
(0,'Secuencia finita|DTFT sobre ω elegidas|Curva + muestras DFT opcionales','ω inicial y final: Intervalo creciente en rad/muestra, por ejemplo −pi a pi.\nPuntos: Número de frecuencias evaluadas, al menos dos; no es la cantidad de muestras de entrada.','DTFT es una curva periódica; DFT son muestras de esa curva. La fase principal salta entre −π y π.'),
(1,'Registro continuo|∫ x(t)e⁻ʲωᵗdt|Espectro continuo aproximado','Entrada: Registro continuo con inicio, paso en segundos y cantidad.\nω inicial/final y puntos: Intervalo en rad/s y cantidad de evaluaciones; más puntos de frecuencia no alargan el registro.','El espectro corresponde al registro finito. Una ventana corta y un paso temporal grande pueden afectar la aproximación.'),
(3,'X(ω) sobre banda finita|∫ X(ω)eʲωᵗdω/(2π)|Señal temporal aproximada','Espectro: Valores complejos; inicio y paso en rad/s.\nt inicial/final y puntos: Intervalo temporal deseado, creciente y con al menos dos puntos.','La banda truncada afecta la salida. Los límites temporales de salida no amplían la banda del espectro de entrada.'),
(4,'x(t) durante un período T|c[k], k = −K…K|Síntesis con armónicos','Inicio y T: Un período completo de la señal; T positivo en segundos.\nK: Entero no negativo; produce 2K+1 armónicos.\nPuntos temporales: Resolución para integrar un período; no cantidad de armónicos.','Los coeficientes son discretos. Aumentar K puede mejorar la síntesis, pero no elimina el fenómeno de Gibbs en discontinuidades.'),
(5,'Un período de N muestras|c[k] = DFT(x)/N|Síntesis periódica','Entrada: Un período completo, con su origen.\nSíntesis: Reutilizá coeficientes de serie discreta, que conservan período y origen.','La normalización difiere de la DFT. Los coeficientes se muestran como muestras no conectadas.'),
(6,'Espectro complejo X|Densidad = |X|²|Distribución de energía','Entrada: Espectro complejo, no una densidad ya elevada al cuadrado.\nEje: Conserva las unidades y el paso del espectro cargado.','Para energía, integrá la densidad con la convención correspondiente; la altura aislada no es energía por sí sola.'),
(7,'Registro, ventana y segmentos|Periodograma / Welch|Densidad de potencia','Fs: Tasa positiva en muestras/s.\nSegmento y solape: Cantidad de muestras por segmento y compartidas con el siguiente; solape menor que segmento.\nVentana y media: Ponderación y resta opcional de la media de cada segmento.','La PSD no tiene fase. En dB se usa 10 log10 de la densidad, no 20 log10. La integral usa las unidades del eje mostrado.')]:add('fourier',task,flow,parameters,reading)
for kind,task,var,out in [('dtft_symbolic',0,'n','ω (rad/muestra)'),('fourier_symbolic',0,'t','ω (rad/s)'),('fourier_symbolic',1,'w','t (s)')]:
    add(kind,task,'Expresión en '+var+'|Transformada algebraica|Resultado en '+out,'Expresión: Usá '+var+' como variable e incluí los tramos del soporte.\n'+('Índices inicial y final: Enteros; se admite -oo u oo para sumas infinitas.\n' if kind=='dtft_symbolic' else '')+'Registro numérico: Inicio, final y cantidad controlan dónde muestrear el resultado ya resuelto, no la transformada algebraica.','Primero calculá la expresión; después graficá muestras. Las deltas y expresiones sin resolver no se convierten en alturas finitas.')
for task,flow,params,reading in [
(0,'x(t), t₀ y Fs|tₙ=t₀+n/Fs|Muestras x(tₙ)','x(t): Fórmula con t en segundos.\nFs: Muestras por segundo, positiva; no rad/s.\nInicio y cantidad: t₀ en segundos y N entero positivo; último instante t₀+(N−1)/Fs.','Los tallos son las muestras. Aumentar N alarga el registro; aumentar Fs reduce la separación temporal.'),
(1,'Frecuencia f y tasa Fs|Plegado a [−Fs/2, Fs/2]|Tono original y alias','Frecuencia: Frecuencia del tono en Hz, no rad/s.\nFs: Tasa positiva en muestras/s. Para convertir una frecuencia angular: f=Ω/(2π).','El dibujo usa un coseno de fase cero y 17 muestras. No demuestra el contenido de banda de una señal arbitraria.'),
(2,'Muestras y factor entero|Diezmar / expandir / interpolar|Registro a otra tasa','Método y factor: Diezmar conserva una de cada M; expandir inserta L−1 ceros; interpolar estima valores. Factor entero positivo.\nFase de diezmado: Posición local de la primera muestra conservada, entre 0 y M−1; no fase angular.','Diezmar aquí no incluye antialias. Expandir no equivale a reconstruir muestras intermedias.'),
(3,'Muestras, Fs y t₀|Retención / rectas / sinc|Curva entre muestras','Fs y t₀: Ubican las muestras en el tiempo; deben corresponder a su adquisición.\nFactor L: Puntos por intervalo, entero positivo.\nMétodo: Retención mantiene valores; lineal une con rectas; sinc usa el registro finito.','La curva termina en la última muestra. No recupera información perdida por aliasing.'),
(4,'Señal y rango de amplitud|Asignar niveles finitos|Señal cuantizada y error','Bits: Determinan la cantidad de niveles.\nMínimo y máximo: Límites ordenados de amplitud, no frecuencias.\nMétodo y cero: Controlan cómo se elige el nivel y si se centra un nivel en cero.\nFilas SNR: Recortan el cálculo de la relación señal/error, no el registro cuantizado.','SNR incluye saturación y no resta la media. El error guardado es xq−x.'),
(5,'Valor y bits I,F|Paso = 2⁻ᶠ|Código, valor y error','Valor: Número a representar; admite el formato exacto indicado.\nBits enteros I: Incluyen el signo; no son sólo bits de magnitud.\nBits fraccionarios F: Controlan el paso 2⁻ᶠ.\nMétodo: Redondeo o truncamiento; los extremos saturan.','Código binario y valor representado son cosas distintas. El error total de este informe se expresa como entrada−salida.')]:add('sampling',task,flow,params,reading)
for task in range(12):
    flows={0:'Cortes y longitud|FIR por ventana|h[n] y respuesta',1:'ω₀ y Q|Biquad de segundo orden|Módulo y fase',2:'R, C y etapas|Circuito RC ideal|Respuesta y componentes',3:'b, a y dominio|Construir H(s) o H(z)|Transferencia reutilizable',4:'Sistema y rango ω|Evaluar H(jΩ) o H(eʲω)|Módulo, dB y fase',5:'Sistema y señal|Ecuación en diferencias|Respuesta desde reposo',6:'Polos, ceros, ganancia|Construir transferencia|Plano complejo y sistema',7:'H(s) y T|Bilineal|H(z)',8:'ωn, ζ y K|Sistema de segundo orden|Transferencia y respuesta',9:'Entrada y sistema|Respuesta temporal|Entrada y salida',10:'Sistema, K y signo|Cerrar realimentación|Transferencia equivalente',11:'Sistema y valores K|Raíces de A+KB|Trayectorias de polos'}
    extra={0:'Cortes: Entre 0 y π rad/muestra; inferior menor que superior. Son cortes del diseño por ventana, no bordes separados de paso y rechazo.\nCoeficientes: Longitud entera; orden = longitud−1.\nVentana: Kaiser añade β; no se usa β para otras ventanas.',1:'ω₀: Entre 0 y π rad/muestra.\nQ: Positivo; controla resonancia/ancho de banda. En el pasabanda implementado la ganancia de pico es Q.',2:'R y C: Ohmios y faradios, positivos; 1 µF = 0.000001 F.\nEtapas: Cascada ideal sin carga.\nDiseño por corte: fc en Hz y un componente conocido; calcula el otro para una etapa.',3:'Tablas: Cada celda corresponde a la potencia mostrada; no omitas términos cero.',4:'Rango y puntos: Inicio menor que final, al menos dos evaluaciones. rad/muestra en discreto, rad/s en continuo.\nEscala: Lineal conserva visualmente anchos iguales; logarítmica requiere inicio positivo y compara razones.',5:'Entrada: Secuencia local para filtrar.\nCantidad: Para respuesta a impulso o escalón, número entero positivo de muestras.',6:'Coordenadas: Real horizontal, imaginaria vertical. Un complejo como 0.5+0.2i define una ubicación.\nPares conjugados: Permiten coeficientes reales.\nGanancia: Multiplica H, no desplaza puntos.\nMouse: Elegí agregar, mover o quitar antes de actuar; actualizá para reutilizar.',7:'T: Período positivo en segundos. La bilineal relaciona Ω=(2/T)tan(ω/2); no conserva linealmente todas las frecuencias.',8:'ωn: Frecuencia natural positiva en rad/s.\nζ: Razón de amortiguamiento; no es una frecuencia.\nK: Ganancia del modelo.',9:'Entrada: Escalón, impulso o señal propia.\nDuración/cantidad: Segundos para continuo; muestras para discreto. Una entrada propia determina el eje de salida.\nValores anteriores: x[n₀−1], y[n₀−1] y anteriores; cero representa reposo.',10:'K y signo: La realimentación negativa usa denominador 1+KH; la positiva usa 1−KH.',11:'K inicial/final y puntos: Intervalo de ganancia y número de valores para seguir las raíces; no es una rejilla de frecuencias.'}[task]
    reading={0:'La forma de la respuesta depende de la ventana y longitud. Módulo es amplitud; dB es 20 log10 |H|.',1:'Una ganancia de pico distinta de uno no implica un error gráfico.',2:'El eje de frecuencia puede ser logarítmico: distancias iguales representan razones iguales, no diferencias.',3:'Definir coeficientes no calcula automáticamente una salida temporal; enviá el sistema a la herramienta deseada.',4:'No se debe comparar ancho visual de transiciones en eje logarítmico como si fuera lineal. Fase no definida en ceros.',5:'La salida usa condiciones iniciales nulas. Para historial no nulo, usá Respuesta temporal.',6:'Cruces son polos y círculos son ceros. La escala de ambos ejes debe ser igual; el círculo unidad debe verse circular.',7:'Se conserva la entrada H(s); la salida H(z) es la que se exporta o reutiliza.',8:'Subamortiguado, crítico y sobreamortiguado describen regímenes diferentes; no son errores de escala.',9:'Parte real conserva signos. Un impulso continuo puede incluir una delta indicada por su peso; no se dibuja como altura finita.',10:'La transferencia externa no basta para demostrar estabilidad interna si hay cancelaciones.',11:'Los ejes son parte real e imaginaria, no tiempo. Mayor resolución de K ayuda a seguir ramas cerca de cruces.'}[task]
    add('systems',task,flows[task],(TRANSFER+'\n' if task in (3,4,5,7,9,10,11) else '')+extra,reading)
for task,flow,extra,reading in [
('analysis','Matrices A,B,C,D|Polos y rangos|Estabilidad y estructura','Rangos: Controlabilidad y observabilidad se estiman numéricamente.','La estabilidad interna depende de A; no sólo del canal externo elegido.'),
('simulation','Matrices, u y estado inicial|Propagar x|y=Cx+Du','Entrada: Una expresión por canal, separadas por ;. Las expresiones se evalúan sobre tiempo físico t.\nEstado inicial: Un valor por estado; vacío usa ceros.\nPaso y puntos: Separación temporal positiva y cantidad de instantes.','En continuo se mantiene la entrada constante entre puntos (ZOH). Parte real conserva signos de estados y salidas.'),
('frequency','Matrices y ω físico|C(jωI−A)⁻¹B+D|Canales salida/entrada','Rango: En rad/s incluso para modelos discretos, donde z=exp(iωT).\nCanal: Cada curva corresponde a un par entrada/salida.','El período T convierte frecuencia física a rad/muestra: ωdigital=ΩT. No confundir estas unidades.'),
('discretize','Modelo continuo y T|ZOH o Tustin|Matrices discretas','T: Período positivo en segundos.\nMétodo: ZOH supone entrada constante por intervalo; Tustin es bilineal.','Las matrices de salida corresponden al período elegido; cambiar T requiere recalcular.'),
('transfer','Modelo y canales|Seleccionar entrada y salida|H de un canal','Canales: Se numeran desde 1. Deben existir en las dimensiones de B, C y D.','Un canal puede ocultar modos internos no observables/controlables; no describe por sí solo todo el modelo.')]:add('state_space',task,flow,MATRICES+'\n'+extra,reading)
add('system_analysis',0,'Coeficientes y dominio|Análisis algebraico y numérico|Fórmula, módulo y fase',TRANSFER+'\nFrecuencias: Intervalo creciente, rad/s para continuo y rad/muestra para discreto.\nPuntos: Resolución del dibujo, al menos dos; no modifica H.','La evaluación numérica necesita coeficientes sin parámetros libres. Una expresión algebraica puede conservarlos.')
add('interconnection',0,'H₁ y H₂|Cascada / paralelo / retorno|Sistema equivalente',TRANSFER+'\nConexión: Cascada multiplica; paralelo suma. Retorno negativo H₁/(1+H₁H₂), positivo H₁/(1−H₁H₂).\nDominio común: Ambos sistemas deben ser continuos o ambos discretos.','Se suponen condiciones iniciales nulas. Estabilidad externa e interna no siempre coinciden.')
for task,flow,params,reading in [
(0,'x(t), t≥0|Laplace unilateral|X(s) y convergencia','Expresión: Fórmula en t, por ejemplo exp(-t). No se pide un intervalo numérico.','La transformación es unilateral; revisá el semiplano y las condiciones del resultado.'),
(1,'X(s)|Inversa causal de Laplace|x(t)','Expresión: Fórmula en s, por ejemplo 1/(s+1).','La herramienta elige la interpretación causal indicada, no todas las señales bilaterales posibles.'),
(2,'Registro x[n]|Σ x[n]z⁻ⁿ|Expresión en z',SEQUENCE,'Se conservan índices negativos si existen. No se supone que el registro se repite infinitamente.'),
(3,'Función racional X(z)|Expansión desde z=∞|Secuencia derecha y términos','Expresión: Función racional en z, por ejemplo z/(z-1/2).\nTérminos: Cantidad de valores mostrados; no define la región de convergencia.','Esta opción usa rama derecha. Para elegir otra región, usá Z inversa con región de convergencia.'),
(4,'a₀…aₘ, f(t), condiciones|a₀y+a₁y′+…=f(t)|Solución de la EDO','Expresión: Es el término forzante f(t), no la ecuación completa.\nCoeficientes: Orden ascendente de derivadas: 1, 2, 1 significa y+2y′+y″.\nIniciales: y(0), y′(0), …; una condición por derivada hasta orden m−1.','No confundir este orden con coeficientes de polinomios en s. Revisá condiciones y estado de evaluación.')]:add('symbolic',task,flow,params,reading)
add('rational_resampling',0,'x[n] y factores L/M|Filtro antialias y cambio de tasa|Fs nueva = Fs·L/M','L y M: Enteros positivos, numerador y denominador de la relación de tasas.\nVentana y filtro: Determinan la aproximación antialias.\nBordes: La extensión elegida afecta inicio y final del registro.','Cambiar la tasa no aumenta la información original. Los valores cercanos a extremos dependen de la extensión.')
add('random','generate','Distribución y parámetros|Generación con semilla|Una realización finita','Media y desviación: Parámetros teóricos de gaussiana/uniforme; desviación no negativa.\nProbabilidad: En Bernoulli, valor entre 0 y 1 de obtener 1.\nCantidad y origen: Longitud positiva y primer índice.\nSemilla: Entero que permite repetir la realización.','El promedio medido puede diferir de la media teórica. En uniforme, extremos = media ± √3·desviación.')
add('random','statistics','Registro y componente|Medir y agrupar amplitudes|Estadísticas e histograma','Componente: Real, imaginaria o módulo para el histograma.\nIntervalos: Número de barras, entero positivo; no cantidad de muestras de entrada.','El eje horizontal es amplitud. El área del histograma representa probabilidad; una altura puede superar 1 si las barras son angostas.')
add('random_correlation',0,'Registro y retardo máximo|Promediar productos|Autocorrelación / covarianza','Retardo: Máximo número de muestras de desplazamiento, menor que la longitud.\nRestar media: Calcula autocovarianza estimada.\nDivisor: N o N−|k| cambia el peso de retardos grandes.\nNormalizar: Divide por el valor en retardo cero cuando está definido.','Retardos grandes usan menos pares. El registro no prueba estacionariedad ni independencia del proceso.')
for task,flow,params,reading in [
('fft','L muestras y ventana|FFT de NFFT puntos|Espectro y referencia DTFT','L: Muestras observadas; cero usa todas.\nNFFT: Al menos L; agregar ceros densifica frecuencias.\nVentana y β: β sólo para Kaiser.\nPuntos DTFT: Densidad de la curva de referencia.','Agregar ceros no mejora la separación de tonos que el registro no resuelve.'),
('fir','Tipo y bordes ordenados|Ventana y tolerancias|FIR y bandas verificadas','Tipo y frecuencias: Seguí los números del dibujo de izquierda a derecha.\nTolerancias: Amplitudes lineales entre 0 y 1.\nLongitud: Cantidad de coeficientes; cero estima Kaiser.','Igual ancho requiere igual diferencia de frecuencias. Las franjas son especificaciones; las ondulaciones pertenecen a la respuesta.'),
('iir','Tipo, bordes y tolerancias|Familia IIR|Filtro y respuesta','Tipo y frecuencias: Un valor por casilla, orden creciente entre 0 y π.\nδp y δs: Tolerancias lineales, no dB.\nMétodo: Familia digital o conversión de prototipo.','Igual especificación no obliga a igual fase u orden entre familias. Compará módulo, fase y respuesta temporal.'),
('convert','H y período T|Elegir transformación|Sistema convertido',TRANSFER+'\nT: Segundos, positivo.\nMétodo: Bilineal/invarianza requieren H(s); las inversas H(z).','La bilineal deforma frecuencias; la invarianza puede introducir aliasing. Su inversa no es única.'),
('gain','H, frecuencia y objetivo|Escalar numerador|Módulo objetivo en esa frecuencia',TRANSFER+'\nFrecuencia: rad/s en continuo o rad/muestra en discreto.\nObjetivo: Amplitud positiva; no dB.','No se puede fijar una ganancia no nula en un cero de H mediante un factor finito.'),
('phase','H(z)|Elegir el ajuste de fase|Sistema ajustado y complemento',TRANSFER,'Fase mínima conserva el módulo mediante reflexión de ceros y compensación de ganancia. Fase lineal exacta usa un complemento conjugado invertido y eleva el módulo al cuadrado; un IIR puede requerir una realización no causal. El informe incluye fórmulas y condiciones.'),
('inverse_z','H(z), región y radio|Integración en contorno|Secuencia bilateral aproximada',TRANSFER+'\nRegión: Exterior, interior, círculo unidad o radio manual. No puede atravesar polos.\nInicio y cantidad: Tramo de índices que se obtiene.\nPuntos: Resolución del contorno, no longitud de salida.','La misma expresión H(z) puede representar señales distintas según la región de convergencia.'),
('band','X(ω) y dos extremos|Integrar |X|²/(2π)|Energía en esa banda','Extremos: Menor y mayor dentro del eje del espectro.\nEntrada: Espectro complejo, no PSD ni densidad ya calculada.','No se duplica automáticamente la banda positiva. Una ventana finita no demuestra la energía total.'),
('lines','Coeficientes c[k] y T|Pesos 2π|c[k]|²|Potencia y líneas espectrales','Coeficientes: Serie continua con sus índices k.\nT: Período positivo en segundos; se conserva si viene del resultado.','Los tallos representan pesos de deltas, no alturas finitas de una densidad.'),
('mapping','ω, Ω o T|Bilineal o muestreo|Frecuencia / período compatible','ω: rad/muestra. Ω: rad/s. T: segundos positivos.\nRama k: Entero para la ambigüedad del muestreo; no aplica a bilineal.','Muestreo relaciona ω y ΩT módulo 2π. Bilineal usa tangente y no produce un mapeo lineal.')]:add('course_tools',task,flow,params,reading)
add('frequency_filter',0,'H(ω) definido por tramos|Y=HX e inversión numérica|H, h, X, Y y salida','Valor y condición: Valor de H y condición sobre w; ejemplo valor 1 cuando abs(w)<=pi/4, cero en los demás casos.\nDominio: Discreto usa rad/muestra y un período [−π,π]; continuo usa rad/s y una banda finita.\nIntervalo de h: Define el tramo temporal aproximado, no los cortes de H.','Un filtro ideal puede ser no causal y de duración infinita. La respuesta temporal mostrada es una aproximación, no un FIR/IIR exacto.')

GUIDES['course_tools','fir']['parameters'] += [('Estimación Kaiser','Usa min(δp,δs) y el menor ancho de transición. No usa el ancho de la banda de paso. Ejemplo: δp=0.05 y δs=0.01 → tolerancia 0.01; transiciones 0.10π y 0.05π → ancho 0.05π. Cada corte queda en el punto medio de su transición. La longitud manual reemplaza la estimada; la búsqueda comprueba candidatos contra todas las bandas originales.')]
GUIDES['rational_resampling',0]['parameters'] += [('Fs de entrada','Tasa positiva en muestras/s; Leer Fs registrada toma el reloj guardado si existe.'),('Semilongitud FIR por fase','Entero positivo que controla la extensión del filtro; mayor longitud implica mayor costo y puede mejorar el rechazo.'),('β de Kaiser','Parámetro de forma de la ventana; no es una frecuencia ni una tolerancia de amplitud.')]
GUIDES['signal_editor',0]['parameters'][1]=('Origen y paso','En discreto, origen entero y paso fijo 1. En continuo, origen en segundos y paso positivo en segundos por fila. Cambiar el eje no interpola los valores. Aplicar edición valida y aplica nombre, eje y muestras juntos.')
GUIDES['signal_editor',0]['reading']='Muestras conserva el borrador; Resultado contiene la última edición aplicada, con gráfico externo, valores, exportación y envío a otra herramienta. Editar el borrador no modifica una salida ya enviada. Se conserva la entrada original. Un registro continuo finito no define una función continua exacta ni términos Dirac.'

GUIDES['fourier',6]={'flow':('Señal propia o espectro X','Transformar si hace falta y obtener |X|²','Densidad y espectro exportables'),'parameters':[('Partir de','Señal discreta x[n], continua x(t) o espectro X(ω). Cada opción admite definición local; no hace falta calcular en otro menú.'),('Frecuencias y puntos','Para señales, definen el intervalo de la transformada: rad/muestra en discreto y rad/s en continuo.'),('Espectro propio','Definí valores complejos X y su eje. No ingreses una PSD ni una densidad ya calculada.')],'reading':'La densidad es |X|². La energía de una banda se obtiene integrando con el factor 1/(2π). La banda finita sólo representa parte del espectro.'}

add('dsp_extensions','hilbert','Señal real x|z = x + j Hilbert(x)|Hilbert, señal analítica y envolvente','Dominio: Secuencia o registro continuo; la entrada debe ser real.\nVentana temporal: Se conserva el eje y se transforma el registro completo; la FFT supone repetición periódica.','La parte imaginaria de z es Hilbert(x) y |z| es la envolvente. En continuo es una aproximación sobre muestras, no una transformada algebraica sobre todo el eje.')
add('dsp_extensions','stft','Señal y ventana|FFT de tramos solapados|Mapa tiempo-frecuencia y espectros locales','Longitud: Entre 2 y las muestras de entrada.\nSolapamiento: Muestras compartidas; entre cero y longitud menos uno.\nPuntos FFT: Al menos la longitud de ventana; el relleno no mejora la resolución temporal.\nVentana: Ponderación periódica para FFT; β sólo corresponde a Kaiser.','Cada columna es FFT(tramo por ventana)/suma(ventana). El mapa usa dB relativos al máximo global, no PSD calibrada. Frecuencias en rad/muestra o rad/s. El último tramo incompleto se rellena con ceros; los valores exportados no se recortan al rango de colores.')
add('dsp_extensions','blocks','x[n], h[n] y L|Convolución mediante FFT por bloques|Salida completa de N+M−1 muestras','Muestras nuevas L: Entero positivo.\nSolapamiento: M−1, con M igual a la longitud de h.\nFFT: Se elige una longitud eficiente mayor o igual a L+M−1.','Overlap-add suma las colas de bloques independientes. Overlap-save incorpora historia y descarta M−1 salidas contaminadas por circularidad. Fuera de las entradas se supone cero y el origen de salida suma ambos orígenes.')

add('course_tools','analog','Bandas Ωp, Ωs y tolerancias|Orden y H(s) de cada familia|Respuesta, informe y sistema reutilizable','Bordes: Valores positivos en rad/s. No hay límite π; deben dejar transiciones de ancho positivo.\nδp: Pérdida de amplitud permitida; paso entre 1−δp y 1.\nδs: Máximo módulo en rechazo, menor que 1−δp.\nFamilia: Butterworth, Chebyshev I/II, elíptico o comparación.','La rejilla incluye los bordes; el informe distingue orden del prototipo y orden final. El modelo es una transferencia analógica, no un circuito ya sintetizado. El gráfico logarítmico muestra desde un décimo del menor borde hasta diez veces el mayor.')

add('course_tools','bandpass_sampling','Bordes ΩL y ΩH|Intervalos sin solapamiento|Tasas, gráfico e informe exportables','ΩL: Borde inferior positivo de la señal, en rad/s.\nΩH: Borde superior, mayor que ΩL.\nΩs a consultar: Frecuencia angular de muestreo, positiva y opcional. Ωs = 2π Fs; no es Fs en muestras/s.','Cada zona m admite un intervalo diferente. No cualquier tasa superior a 2B sirve. Elegí el interior para dejar margen; los extremos y los intervalos de ancho nulo son contactos teóricos. Se supone señal real y soporte limitado a ±[ΩL, ΩH]. El gráfico muestra hasta 40 zonas y el informe hasta 100; CSV conserva todas. No se interpreta una componente impulsiva en un borde como reconstrucción garantizada.')

for _task in ('fir','iir','analog','convert','gain','phase'):
    GUIDES['course_tools',_task]['reading']+=' El retardo de grupo se evalúa con la derivada analítica de los polinomios, en muestras para H(z) y segundos para H(s). En filtros SOS se suman los retardos de sus secciones sin expandirlas. No depende del desenrollado de la fase dibujada. Los ceros, polos y puntos con cancelación numérica severa se omiten; no se reemplazan por retardo cero.'


# Convenciones comunes de lectura del eje y términos ideales.
for guide in GUIDES.values():
    guide['reading']+=' Ejes: n o k son índices enteros; cada índice tiene su marca cuando la escala permite distinguirlas y los números se espacian para no superponerse. La barra del gráfico indica el índice más cercano al mouse y el valor de la muestra dibujada; t y τ se expresan en segundos. Los tallos indican muestras independientes. En frecuencia digital, π rad/muestra es una frecuencia angular, no una frecuencia normalizada; la DTFT es continua y la DFT se representa con tallos.'
GUIDES['basic','continuous_convolve']['reading']+=' Los impulsos Dirac reutilizados se conservan por posición y peso: δ(t−a)*x(t)=x(t−a). La parte regular se interpreta linealmente entre puntos y nula fuera del registro; su integral se evalúa sobre la rejilla de salida.'
GUIDES['time_transform',0]['reading']+=' Un impulso de peso w en τ pasa a τ/a+t₀ con peso A·w/|a|; no se convierte en una muestra de altura finita.'

GUIDES['course_tools','convert']['parameters'] += [
    ('Definir filtro como','Transferencia permite coeficientes H(s)/H(z). Respuesta analógica ideal / por tramos permite escribir Ha(jΩ): usá w como frecuencia Ω en rad/s y el editor por tramos.'),
    ('Conversión de la respuesta','Bilineal evalúa Ha en Ω=(2/T)tan(ω/2). Invarianza usa h[n]=T ha(nT) y suma réplicas en frecuencia.'),
    ('Ωmáx','Sólo para invarianza: se declara Ha=0 fuera de [−Ωmáx,Ωmáx]. Debe incluir todo el soporte del filtro que se desea convertir. Un pasaaltos de soporte infinito no cumple esta hipótesis; usá bilineal o declaralo como aproximación truncada.'),
    ('Puntos digitales','Resolución de la respuesta en rad/muestra. Los puntos son centros de celdas para evitar ±π en el mapeo bilineal. Aumentá su cantidad cerca de saltos ideales.')]
GUIDES['course_tools','convert']['reading']+=' La respuesta ideal se conserva por separado del FIR aproximado obtenido por ventana. Ambos se exportan y reutilizan; el FIR no equivale exactamente al ideal. Un filtro ideal puede ser no causal y tener duración infinita.'

add('filter_lab',0,'Definir o diseñar|Convertir o aplicar|Respuesta y retardo','Analizar: Fórmula H(s)/H(z) o coeficientes; respuesta, retardo de grupo y plano de polos y ceros de consulta.\nDiseñar: FIR, IIR, analógicos y editor de polos y ceros. Ajustar: ganancia y fase. Ideales y por tramos: definir H y analizar o aplicar su respuesta.\nConvertir: Los ideales se aproximan con un FIR por ventana.\nRespuesta temporal: Impulso, escalón o entrada propia.','Cada opción conserva sus datos. Analizar el filtro obtenido lleva el resultado al análisis común sin reescribir coeficientes.')
add('transform_lab','z','x[n] o X(z)|Soporte o ROC|Expresión y muestras','Directa: x[n] usa n; límites enteros, -oo u oo.\nInversa: X(z) racional; la ROC decide soporte derecho, izquierdo o bilateral.\nRadio: Dentro de la ROC, sin atravesar polos.\nMuestras: El intervalo sólo delimita la visualización.','Se muestran condiciones de convergencia. Las potencias positivas de z pueden describir índices negativos.')
add('transform_lab','laplace','x(t) o X(s)|Directa o inversa|Expresión y condiciones','Unilateral o bilateral: x(t).\nInversa: X(s) y ROC.','La ROC determina el soporte temporal. Los cálculos sin evaluar y las regiones vacías se identifican.')
GUIDES['course_tools','convert']['parameters'] += [('Ventana y longitud FIR','Para la respuesta ideal se invierte H, se conserva una cantidad impar de muestras, se aplica la ventana y se desplaza el centro para hacerla causal. El retardo añadido es (L−1)/2 muestras.')]
GUIDES['systems',6]['parameters'] += [('Coordenadas','Binómica usa parte real/imaginaria; polar usa módulo y ángulo en radianes. El mouse edita las mismas raíces. Polos y ceros reales pueden estar a ambos lados de cero.')]

