GUIDES['system_analysis',0]['parameters'] += [('Pestaña Polos y ceros','Después de analizar, seleccionarla calcula y abre el plano s o z del mismo resultado. Es una vista de consulta; no mueve raíces ni modifica H. Permite coordenadas binómicas o polares.') ]
GUIDES['system_analysis',0]['reading'] += ' El criterio de polos usa interpretación causal; en Z la ROC y la causalidad deben verificarse. Una fórmula simplificada no conserva necesariamente la estabilidad interna de una realización anterior.'

GUIDES['filter_lab',0]['parameters']=[('Sistemas LTI','Análisis de H, módulo, fase, retardo, polos y ceros; respuesta temporal e interconexión.'),('Diseño de filtros','FIR, IIR, modelos analógicos, editor de raíces, ajustes, ideales y conversión.'),('Cálculo','La barra superior muestra la acción de la herramienta activa. Ctrl+Enter la ejecuta con sus propios datos.') ]
GUIDES['basic','generate']['parameters'] += [('Dominio','Discreta x[n] usa índices enteros. Continua x(t) usa tiempo en segundos; se define inicio, paso y cantidad.'),('Método de entrada','Expresión, Muestras o Importar se eligen directamente. Dentro de Expresión, Por tramos edita valores y condiciones.')]
