GUIDES['filter_lab',0]['parameters']=[('Sistemas LTI','Analizar un sistema reúne frecuencia, polos/ceros y respuesta temporal. Los filtros ideales están en análisis.'),('Diseño de filtros','Diseñar filtro reúne FIR e IIR. El diseño por ubicación de raíces, modelos físicos, ajustes y conversión permanecen como problemas distintos.'),('Cálculo','La barra superior ejecuta la opción activa. Ctrl+Enter calcula y F1 abre su ayuda.')]


GUIDES['system_analysis',0]['parameters'] += [
    ('Frecuencias y puntos','Desde y Hasta son frecuencias angulares en rad/s para H(s), o rad/muestra para H(z). El intervalo debe crecer e incluye ambos extremos. Puntos controla el muestreo de la curva; no cambia los coeficientes.'),
    ('Eje de frecuencia','Lineal permite cero y frecuencias negativas. Logarítmico exige Desde > 0 y distribuye las evaluaciones por décadas; no sólo cambia las marcas.'),
    ('Módulo lineal o dB','El selector de la barra de la figura cambia la representación sin recalcular ni modificar H. Se usa 20 log10 |H|. Un cero exacto vale −∞ dB y se omite en esa curva; no se inventa un piso.'),
    ('Cruces y márgenes','Es opcional. H se interpreta como L de lazo abierto con realimentación negativa unitaria y coeficientes reales. El cruce |L|=1 da el margen de fase; el cruce de L por el eje real negativo da MG=1/|L|. Los márgenes de fase se expresan en radianes como distancia con signo en [−π,π).'),
    ('Alcance de los márgenes','Se buscan cruces aislados en el intervalo evaluado, refinando cambios de signo y mínimos locales muestreados. Puede haber cruces entre puntos no detectados. En digital se usa sólo 0…π rad/muestra; se excluye frecuencia cero. No encontrar cruces no permite declarar márgenes infinitos. Los tramos críticos no aislados se informan aparte.'),
    ('Interpretación de estabilidad','Márgenes positivos por sí solos no certifican estabilidad del lazo cerrado. Revisá polos inestables, cancelaciones, causalidad y el lazo usado. No se asignan estos márgenes convencionales a coeficientes complejos ni a una fórmula con avance temporal.'),
    ('Exportar respuesta','CSV conserva coordenadas, H real/imaginaria, módulo, dB, fase y retardo. JSON agrega todos los cruces detectados y el alcance. Un eje logarítmico no es uniforme: esta tabla de análisis no se disfraza de una señal de paso constante. Los campos no definidos se exportan vacíos en CSV y null en JSON; −∞ dB se distingue por módulo cero.')]
GUIDES['system_analysis',0]['reading'] += ' La figura mantiene las tres vistas sobre el mismo eje. Cambiar el módulo en la barra de la figura sólo cambia la presentación del último resultado. Para cambiar la distribución o rango de frecuencias, analizá de nuevo.'


